async function ensureSharedVaultKeyForAccount(account: PlatformAccount | undefined): Promise<boolean> {
  if (!account || account.provider === "Polymarket")
    return false;
  const {
    accountTokenHasPrivateKey,
    ensurePmVaultUnlocked,
    hasVault,
    isVaultKeyProvider,
    mergeVaultKeysIntoAccounts,
    normalizePmVaultUserId,
  } = await import("@/security/pmVault");
  if (!isVaultKeyProvider(account.provider))
    return true;
  if (accountTokenHasPrivateKey(account.token))
    return true;

  const user = useUserStore();
  if (!user.userId && user.isLoggedIn)
    await user.fetchUserInfo();
  const uid = normalizePmVaultUserId(user.userId);
  if (!uid || !(await hasVault(uid)))
    return false;
  const unlocked = await ensurePmVaultUnlocked(uid);
  if (!unlocked)
    return false;

  const { useAccountStore } = await import("@/stores/accountStore");
  const accountStore = useAccountStore();
  mergeVaultKeysIntoAccounts(accountStore.accounts, uid);
  const shared = account.accountId ? accountStore.findAccount(Number(account.accountId)) : undefined;
  if (shared?.token && accountTokenHasPrivateKey(shared.token))
    account.token = shared.token;
  return accountTokenHasPrivateKey(account.token);
}

/**
 * delayed 受理后：跟到已成交 / 未成交再提示。
 * 本地查询耗尽仍 pendingConfirm 时保持待确认，后台退避续查。
 */
function notifyPendingVenueConfirm(
  store: AccountStoreContext,
  account: PlatformAccount,
  accountLine: string,
  detailHtml: string,
  result: BetResult,
  option: BetOption,
  toastSeconds: number,
  pendingOrderSave?: Promise<void>,
) {
  const orderId = String(result.orderId ?? "").trim();
  if (!orderId)
    return;
  const pmScope = account.provider === "Polymarket" ? pmSubmitScope(account) : undefined;
  const key = pmScope ? `${pmScope}:${orderId}` : `${account.accountId}:${orderId}`;
  const existing = pendingVenueBetConfirmations.get(key);
  if (existing) {
    if (pendingOrderSave) pendingVenueOrderWrites.set(existing, pendingOrderSave);
    schedulePendingVenueBetConfirmation(store, existing); return;
  }
  const task: PendingVenueBetConfirmation = {
    observation: option.observation,
    linkId: option.diagnosticLinkId,
    key,
    pmScope,
    accountId: account.accountId,
    provider: account.provider,
    orderId,
    matchId: option.matchId,
    venueBetId: option.betId,
    itemId: option.itemId,
    betRowId: Number(option.bet?.id ?? option.betId) || 0,
    target: option.target,
    betMoney: option.betMoney,
    odds: option.odds,
    accountLine,
    detailHtml,
    toastSeconds,
    attempts: 0,
    nextPollAt: Date.now(),
    pmSubmission: account.provider === "Polymarket" ? pmSubmissionFromResult(result, account.accountId) ?? undefined : undefined,
  };
  if (pendingOrderSave) pendingVenueOrderWrites.set(task, pendingOrderSave);
  pendingVenueBetConfirmations.set(task.key, task);
  persistPendingVenueBetConfirmations();
  void runPendingVenueBetConfirmation(store, task);
}

const PENDING_VENUE_CONFIRM_KEY = "PENDING_VENUE_BET_CONFIRM";

interface PendingVenueBetConfirmation {
  pmScope?: string;
  pmSubmission?: PmSubmission;
  /** 已由套利/补单队列计数的尝试，恢复页只核对与同步原单。 */
  recoveryOnly?: boolean;
  observation?: ObservationContext;
  linkId?: number;
  key: string;
  accountId: number;
  provider: string;
  orderId: string;
  matchId: string;
  venueBetId: string;
  itemId: string;
  betRowId: number;
  target: BetOption["target"];
  betMoney: number;
  odds: number;
  accountLine: string;
  detailHtml: string;
  toastSeconds: number;
  attempts: number;
  nextPollAt: number;
}

function loadPendingVenueBetConfirmations(): Map<string, PendingVenueBetConfirmation> {
  try {
    const rows = JSON.parse(sessionStorage.getItem(PENDING_VENUE_CONFIRM_KEY) || "[]") as PendingVenueBetConfirmation[];
    return new Map(rows.filter(row => row?.key && row.orderId).map(row => [row.key, row]));
  }
  catch {
    return new Map();
  }
}

const pendingVenueBetConfirmations = loadPendingVenueBetConfirmations();
const pendingVenueConfirmationFlights = new Set<string>();
const pendingVenueConfirmationTimers = new Map<string, ReturnType<typeof setTimeout>>();
const pendingVenueConfirmationResumeVersions = new Map<string, string>();
// 只串行化同一订单的写入 Promise；名称属于正在保存的订单，不交给确认任务。
const pendingVenueOrderWrites = new WeakMap<PendingVenueBetConfirmation, Promise<void>>();

function pendingVenueAccountMatches(store: AccountStoreContext, task: PendingVenueBetConfirmation): boolean {
  try {
    const live = store.findAccount(task.accountId);
    return live?.provider === task.provider && (!task.pmScope || task.pmScope === pmSubmitScope(live));
  }
  catch { return false; }
}

function persistPendingVenueBetConfirmations(): void {
  try {
    sessionStorage.setItem(
      PENDING_VENUE_CONFIRM_KEY,
      JSON.stringify([...pendingVenueBetConfirmations.values()]),
    );
  }
  catch {
    /* sessionStorage 不可用时仍保留当前页单飞续查 */
  }
}

function schedulePendingVenueBetConfirmation(
  store: AccountStoreContext,
  task: PendingVenueBetConfirmation,
): void {
  if (pendingVenueConfirmationTimers.has(task.key) || pendingVenueConfirmationFlights.has(task.key))
    return;
  const delay = Math.max(0, task.nextPollAt - Date.now());
  const timer = setTimeout(() => {
    pendingVenueConfirmationTimers.delete(task.key);
    void runPendingVenueBetConfirmation(store, task);
  }, delay);
  pendingVenueConfirmationTimers.set(task.key, timer);
}

async function runPendingVenueBetConfirmation(
  store: AccountStoreContext,
  task: PendingVenueBetConfirmation,
): Promise<void> {
  if (pendingVenueConfirmationFlights.has(task.key))
    return;
  if (task.nextPollAt > Date.now()) {
    schedulePendingVenueBetConfirmation(store, task);
    return;
  }
  const account = store.findAccount(task.accountId);
  if (!account) {
    task.nextPollAt = Date.now() + 5_000;
    pendingVenueBetConfirmations.set(task.key, task);
    persistPendingVenueBetConfirmations();
    schedulePendingVenueBetConfirmation(store, task);
    return;
  }
  // 新任务绑定用户/钱包；旧会话仅在当前钱包的持久化原单能核实时迁移。
  if (task.provider === "Polymarket") {
    try {
      if (account.provider !== "Polymarket") return;
      const scope = pmSubmitScope(account);
      if (!task.pmScope && pmAccountSubmitAttempts(account).some(attempt =>
        attempt.orderHash === task.orderId || attempt.acceptedOrderId === task.orderId)) task.pmScope = scope;
      if (!task.pmScope) {
        // 兼容升级前会话：由服务端校验账号归属，再用原签名 maker 核对当前钱包。
        const version = getAuthSessionVersion();
        let recovered;
        try { recovered = validatePmSubmission(await getPmSubmission(account.accountId, task.orderId), task.orderId, account.accountId); }
        catch {
          task.nextPollAt = Date.now() + 5_000;
          schedulePendingVenueBetConfirmation(store, task);
          return;
        }
        if (!isAuthSessionCurrent(version) || scope !== pmSubmitScope(account)) return;
        if (!recovered?.makerAddress || recovered.makerAddress !== pmSubmitMaker(account)) return;
        task.pmSubmission = recovered;
        task.pmScope = scope;
        persistPendingVenueBetConfirmations();
      }
      if (task.pmScope !== scope) return;
    } catch { return; }
  }
  const sessionVersion = getAuthSessionVersion();

  if (pendingVenueConfirmationFlights.has(task.key)) return;
  pendingVenueConfirmationFlights.add(task.key);
  try {
    const result = Object.assign(new BetResult(task.provider as BetOption["type"], true), {
      success: task.pmSubmission?.submitUnknown !== true,
      pmSubmitUnknown: task.pmSubmission?.submitUnknown,
      pmSubmittedAt: task.pmSubmission?.submittedAt,
      ...(task.pmSubmission ? { beginTime: task.pmSubmission.submittedAt,
        request: { order: { side: "BUY", makerAmount: task.pmSubmission.makerAmount, maker: task.pmSubmission.makerAddress,
          ...(task.pmSubmission.takerAmount ? { takerAmount: task.pmSubmission.takerAmount } : {}) } } } : {}),
      orderId: task.orderId,
      pending: true,
      observation: task.observation,
      link: task.linkId || 0,
    });
    const option = new BetOption(
      task.provider as BetOption["type"],
      task.matchId,
      task.venueBetId,
      task.itemId,
      task.betMoney,
      task.target,
      task.odds,
    );
    option.observation = task.observation;
    option.diagnosticLinkId = task.linkId;
    const { rejected, pendingConfirm, orders } = task.provider === "Polymarket"
      ? await confirmVenueBet(account, result, { rejectWaitSec: 0, pmConditionId: task.venueBetId })
      : await settleArbLegUntilTerminal(account, result, { rejectWaitSec: 0, betOption: option });
    if (!isAuthSessionCurrent(sessionVersion) || !pendingVenueAccountMatches(store, task)) return;
    try {
      const exactObservedOrder = orders.find(order => String(order.orderId) === task.orderId);
      observeOption(option, account, "settlement_observed", {
        orderId: task.orderId,
        outcome: pendingConfirm ? "timeout" : rejected ? "unfilled" : "filled",
        source: String(result.message).includes("超时策略判拒") ? "timeout_policy" : exactObservedOrder ? "adapter" : "orchestration_result",
        observedStatus: exactObservedOrder?.status,
        phase: "reject_detection",
      });
    }
    catch { /* 观察快照异常不改变原单确认的后续处理 */ }
    if (pendingConfirm) {
      task.pmSubmission = pmSubmissionFromResult(result, account.accountId) ?? task.pmSubmission;
      task.attempts += 1;
      task.nextPollAt = Date.now() + Math.min(30_000, 1_000 * 2 ** Math.min(task.attempts - 1, 5));
      pendingVenueBetConfirmations.set(task.key, task);
      persistPendingVenueBetConfirmations();
      return;
    }

    if (task.provider === "Polymarket") {
      await pendingVenueOrderWrites.get(task);
      if (!isAuthSessionCurrent(sessionVersion) || !pendingVenueAccountMatches(store, task)) return;
      pendingVenueOrderWrites.delete(task);
      if (rejected) {
        const saved = await persistPolymarketExecutionReject(account, result, "unfilled", { linkId: task.linkId });
        if (!saved) throw new Error("PM 拒单结果保存失败");
      }
      else {
        const filled = orders.find(order => String(order.orderId) === task.orderId
          && !["pending", "reject"].includes(order.status) && Number(order.pmShares) > 0);
        // 成交明细尚未索引或保存失败：保留任务，续查/保存同一单号。
        if (!filled) throw new Error("PM 成交明细尚未同步");
        await saveOrders(account, [filled]);
      }
    }
    if (!isAuthSessionCurrent(sessionVersion) || !pendingVenueAccountMatches(store, task)) return;
    pendingVenueBetConfirmations.delete(task.key);
    pendingVenueConfirmationResumeVersions.delete(task.key);
    persistPendingVenueBetConfirmations();
    const titleSuffix = rejected ? "未成交" : "已成交";
    showBetResultNotification({ provider: account.provider, accountLine: task.accountLine, detailHtml: task.detailHtml }, {
      messageHtml: `<p>${result.message || ""}</p>`,
      statusSuffix: titleSuffix,
      type: rejected ? "error" : "success",
    }, task.toastSeconds);
    if (!rejected && !task.recoveryOnly) {
      void playOrderSuccessSound({ betRowId: task.betRowId || task.venueBetId });
      void publishBettingEvent(option);
      // PF/PM：受理≠成交；成功计数推迟到 filled
      if (isPendingConfirmVenueProvider(account.provider)) {
        const betRowId = Number(task.betRowId);
        if (Number.isFinite(betRowId) && betRowId > 0)
          markSuccessfulBet(account, betRowId, option.target, option.odds);
      }
    }
    if (isPendingConfirmVenueProvider(account.provider)) {
      try {
        const { refreshAccountBalance } = await import("@/stores/account/balanceRefresh");
        await refreshAccountBalance(store, account);
      }
      catch {
        /* 刷新失败不阻断 toast */
      }
      try {
        const { refreshOrderListAfterBind } = await import("@/stores/betting/arbOrderBind");
        refreshOrderListAfterBind();
      }
      catch {
        /* 侧栏刷新失败不阻断 toast */
      }
    }
  }
  catch {
    if (pendingVenueBetConfirmations.has(task.key)) {
      task.attempts += 1;
      task.nextPollAt = Date.now() + Math.min(30_000, 1_000 * 2 ** Math.min(task.attempts - 1, 5));
      pendingVenueBetConfirmations.set(task.key, task);
      persistPendingVenueBetConfirmations();
    }
  }
  finally {
    pendingVenueConfirmationFlights.delete(task.key);
    const current = pendingVenueBetConfirmations.get(task.key);
    const resumedVersion = pendingVenueConfirmationResumeVersions.get(task.key);
    if (current && pendingVenueAccountMatches(store, task)
      && (isAuthSessionCurrent(sessionVersion) || resumedVersion != null && isAuthSessionCurrent(resumedVersion)))
      schedulePendingVenueBetConfirmation(store, current);
  }
}

/** 账号加载后恢复手动/正 EV 单的场馆待确认任务。 */
export function resumePendingVenueConfirmations(store: AccountStoreContext): void {
  void restoreStoredPendingPmOrders(store);
  for (const account of store.accounts ?? []) {
    if (account.provider !== "Polymarket") continue;
    try {
      for (const attempt of pmAccountSubmitAttempts(account)) {
        const recovery = attempt.recovery;
        if (attempt.side !== "BUY" || !recovery) continue;
        const orderId = attempt.acceptedOrderId || attempt.orderHash;
        const pmScope = pmSubmitScope(account);
        const key = `${pmScope}:${orderId}`;
        const pmSubmission: PmSubmission = { orderId, accountId: account.accountId, makerAmount: attempt.makerAmount,
          stakeUsdc: Number(attempt.makerAmount) / 1e6, submittedAt: attempt.submittedAt,
          makerAddress: pmSubmitMaker(account),
          ...(attempt.takerAmount ? { takerAmount: attempt.takerAmount } : {}),
          submitUnknown: !attempt.acceptedOrderId };
        const legacy = [...pendingVenueBetConfirmations.values()].find(task => task.provider === "Polymarket"
          && task.accountId === account.accountId && task.orderId === orderId && (!task.pmScope || task.pmScope === pmScope));
        if (legacy) {
          Object.assign(legacy, recovery, { pmScope,
            pmSubmission: validatePmSubmission({ ...legacy.pmSubmission, ...pmSubmission }, orderId, account.accountId) ?? pmSubmission });
          continue;
        }
        if (pendingVenueBetConfirmations.has(key)) continue;
        pendingVenueBetConfirmations.set(key, { ...recovery, target: recovery.target as BetOption["target"],
          key, pmScope, accountId: account.accountId, provider: "Polymarket", orderId,
          betRowId: recovery.betRowId ?? 0, accountLine: "", detailHtml: "",
          toastSeconds: 3, attempts: 0, nextPollAt: Date.now(),
          pmSubmission });
      }
    } catch { /* 凭证尚未加载时保留原记录，下次恢复 */ }
  }
  persistPendingVenueBetConfirmations();
  for (const task of pendingVenueBetConfirmations.values()) {
    pendingVenueConfirmationResumeVersions.set(task.key, getAuthSessionVersion());
    schedulePendingVenueBetConfirmation(store, task);
  }
}


const pendingPmRestoreFlights = new Set<string>();
const pendingPmRestoreTimers = new Map<string, ReturnType<typeof setTimeout>>();
async function restoreStoredPendingPmOrders(store: AccountStoreContext): Promise<void> {
  await Promise.allSettled((store.accounts ?? []).filter(account => account.provider === "Polymarket")
    .map(account => restoreStoredPendingPmAccount(store, account)));
}

async function restoreStoredPendingPmAccount(store: AccountStoreContext, account: PlatformAccount): Promise<void> {
  let scope: string;
  try { scope = pmSubmitScope(account); } catch { return; }
  const version = getAuthSessionVersion();
  const flightKey = JSON.stringify([version, scope, account.accountId]);
  if (pendingPmRestoreFlights.has(flightKey)) return;
  const retry = pendingPmRestoreTimers.get(flightKey);
  if (retry) { clearTimeout(retry); pendingPmRestoreTimers.delete(flightKey); }
  pendingPmRestoreFlights.add(flightKey);
  const current = () => {
    try {
      const live = store.findAccount(account.accountId);
      return isAuthSessionCurrent(version) && live?.provider === "Polymarket" && scope === pmSubmitScope(live);
    }
    catch { return false; }
  };
  try {
    const rows = await getPendingPmOrders(account.accountId);
    if (!current()) return;
    for (const row of rows) {
      const submission = validatePmSubmission(row.submission, row.orderId, account.accountId);
      if (!submission?.makerAddress || submission.makerAddress !== pmSubmitMaker(account)) continue;
      const existing = [...pendingVenueBetConfirmations.values()].find(task =>
        task.provider === "Polymarket" && task.accountId === account.accountId
        && task.orderId === row.orderId && (!task.pmScope || task.pmScope === scope));
      if (existing) {
        pendingVenueOrderWrites.delete(existing); // RDS 已证实完整订单已保存。
        existing.pmScope = scope;
        existing.pmSubmission = submission;
        existing.matchId ||= row.matchId;
        existing.venueBetId ||= row.conditionId;
        existing.itemId ||= row.tokenId;
        existing.linkId ||= row.linkId;
        persistPendingVenueBetConfirmations();
        schedulePendingVenueBetConfirmation(store, existing);
        continue;
      }
      const key = `${scope}:${row.orderId}`;
      const task: PendingVenueBetConfirmation = {
        key, pmScope: scope, accountId: account.accountId, provider: "Polymarket", orderId: row.orderId,
        matchId: row.matchId, venueBetId: row.conditionId, itemId: row.tokenId,
        target: row.target as BetOption["target"], betRowId: 0, betMoney: submission.stakeUsdc,
        odds: row.odds, linkId: row.linkId, pmSubmission: submission, recoveryOnly: true,
        accountLine: "", detailHtml: "", toastSeconds: 3, attempts: 0, nextPollAt: Date.now(),
      };
      pendingVenueBetConfirmations.set(key, task);
      persistPendingVenueBetConfirmations();
      schedulePendingVenueBetConfirmation(store, task);
    }
  }
  catch {
    if (current()) pendingPmRestoreTimers.set(flightKey, setTimeout(() => {
      pendingPmRestoreTimers.delete(flightKey);
      if (current()) void restoreStoredPendingPmAccount(store, store.findAccount(account.accountId)!);
    }, 5_000));
  }
  finally { pendingPmRestoreFlights.delete(flightKey); }
}

export async function checkBetting(
  _store: AccountStoreContext,
  account: PlatformAccount | undefined,
  option: BetOption,
  opts?: CheckBettingOpts,
) {
  try { option.observation ??= createObservationContext(); }
  catch { /* 不可写对象上的旁路元数据不能阻断预检 */ }
  observeOption(option, account, "precheck_started");
  if (!account) {
    option.checkError = `场馆${option.type}没有可用账号`;
    observeOption(option, account, "precheck_result", { outcome: "blocked", reasonCode: "no_account" });
    return option;
  }
  const pm = account.provider === "Polymarket";
  // [changmen 扩展] PM 交易路径只检查会话有效性；解锁与 signer 初始化由账号生命周期完成。
  if (pm) getRetainedPmPrivateKey(account.accountId);
  else await ensureSharedVaultKeyForAccount(account).catch(() => false);
  const provider = getProvider(account);
  if (!provider) {
    option.checkError = `场馆${option.type}不被支持`;
    observeOption(option, account, "precheck_result", { outcome: "blocked", reasonCode: "unsupported_provider" });
    return option;
  }
  let observedPrecheckResult = false;
  let checkedOption = option;
  const observationStartedAt = Date.now();
  let observationError: unknown;
  try {
    // [changmen 扩展] 人工及重试动态 FOK 在冻结报价前准备；双腿已提前准备，不能在此补等。
    if (pm && opts?.pmOrderMode !== "GTC" && opts?.role !== "precheckOnly" && !opts?.pmDynamicPrepared
      && capturePmFokPreflightMode(option) === "optimized") await prepareOptimizedFokExecution(account);
    attachPolymarketDetectionQuote(option, opts?.pmQuoteScope);
    attachPredictFunDetectionQuote(option);
    // [A8 适配] 编排 Plan CNY → 场馆原币（CNY / U / PM）；预检后不改，跌价由各场馆 checkBet 拒单
    if (!opts?.skipStakeResolve) {
      const planBetMoney = pm ? (option.planBetMoney ?? option.betMoney) : option.betMoney;
      const exchange = getExchange(account.currency);
      const venueBetMoney = resolveVenueStakeFromPlanCny(account, planBetMoney, option.odds, opts);
      option.planBetMoney = planBetMoney;
      option.stakeExchange = exchange;
      option.stakeRate = planBetMoney > 0 ? (venueBetMoney * exchange) / planBetMoney : 1;
      option.stakeCurrency = String(account.currency || "CNY");
      option.betMoney = venueBetMoney;
    }
    const checked = pm && opts?.pmOrderMode === "GTC"
      ? await (await import("@changmen/venue-browser/adapter/polymarket/gtc")).checkGtcBuy(account, option, undefined, opts?.pmGtcAllowResting !== true)
      : await provider.checkBet(account, option, { role: opts?.role ?? "execute", ...(opts?.requireClobConfirmation ? { requireClobConfirmation: true } : {}) });
    checkedOption = checked;
    // [changmen 扩展] adapter 返回新对象时只传递观察元数据，原业务返回值不变。
    try { checked.observation ??= option.observation; }
    catch { /* 观察字段写入失败不改变返回值 */ }
    try {
      // [changmen 扩展] 执行层按 data 判定可继续；数据与错误并存只能记录矛盾，不能宣称已拦截。
      const blocked = !checked.data;
      const inconsistent = !blocked && Boolean(checked.checkError);
      observeOption(checked, account, "precheck_result", { outcome: blocked ? "blocked" : inconsistent ? "inconsistent" : "prepared", durationMs: Date.now() - observationStartedAt,
        reasonCode: blocked ? "precheck_error" : inconsistent ? "precheck_inconsistent" : undefined,
        ...(blocked ? observationFailureEvidence(checked.checkError || "无盘口数据", checked.response, undefined, account.provider) : {}),
        ...(inconsistent ? { safeSummary: "预检同时返回盘口数据和错误，不能据此认定已拦截；是否提交请查看提交记录" } : {}) });
    }
    catch { /* 观察快照读取失败不改变 adapter 返回值 */ }
    observedPrecheckResult = true;
    return checked;
  }
  catch (e) {
    observationError = e;
    // [A8 可证实] RAY 预检沿用 account store 的 JSON.stringify(error)，包括盘口缺项异常。
    option.checkError = account.provider === "RAY" ? JSON.stringify(e)
      : e instanceof Error ? e.message : JSON.stringify(e);
    return option;
  }
  finally {
    if (!observedPrecheckResult) {
      try {
        const inconsistent = Boolean(option.data);
        observeOption(option, account, "precheck_result", {
          outcome: inconsistent ? "inconsistent" : "blocked", reasonCode: inconsistent ? "precheck_inconsistent" : "precheck_error", durationMs: Date.now() - observationStartedAt,
          ...(inconsistent ? { safeSummary: "预检抛出异常但仍保留盘口数据，不能据此认定已拦截；是否提交请查看提交记录" }
            : observationFailureEvidence(option.checkError, undefined, observationError)),
        });
      }
      catch { /* 旁路证据读取失败不阻断预检收尾 */ }
    }
    try { checkedOption.saveLog(account); }
    catch { /* 预检日志失败不能改变冻结盘口或阻断原单发送。 */ }
  }
}

export async function placeBet(
  store: AccountStoreContext,
  account: PlatformAccount | undefined,
  option: BetOption,
  toastSeconds = 10,
  opts?: PlaceBetOpts,
) {
  try {
    option.observation ??= createObservationContext();
    if (opts?.linkId)
      option.diagnosticLinkId = opts.linkId;
  }
  catch { /* 不可写对象上的旁路元数据不能阻断提交 */ }
  if (!account) {
    observeOption(option, account, "submission_result", { outcome: "not_submitted", reasonCode: "no_account" });
    return new BetResult(option.type, false, "无可用账号");
  }
  // [changmen 扩展] 冻结预检已完成钱包准备，首腿成功后不再重启解锁链路。
  if (account.provider !== "Polymarket" && !opts?.requirePreparedQuote) await ensureSharedVaultKeyForAccount(account);
  const provider = getProvider(account);
  if (!provider) {
    observeOption(option, account, "submission_result", { outcome: "not_submitted", reasonCode: "unsupported_provider" });
    return new BetResult(option.type, false, "平台不支持");
  }

  let accountLine = "", detailHtml = "";
  try {
    const platformLabel = store.getPlatformName(account.platformId, account.platformName);
    accountLine = bettingNotifyAccountLine(account, platformLabel);
    detailHtml = bettingDetailHtml({
      matchTitle: option.match?.title,
      betName: option.bet?.getBetName(),
      target: option.target,
      itemOdds: option.item?.getOdds(option.target),
      betMoney: option.betMoney,
      odds: option.odds,
      betCount: option.betCount,
    });
  }
  catch { /* 展示数据读取失败不能阻断已经预检的场馆发送。 */ }

  const notificationDisplay = { provider: account.provider, accountLine, detailHtml };
  const loading = startBetNotification(notificationDisplay);

  const beginTime = Date.now();
  let result: BetResult = new BetResult(account.provider, false, "未知错误");
  let observationSubmitted = false;
  let observationThrew = false;
  let observationCallAt: number | undefined;
  let observationDuration: number | undefined;
  let observationError: unknown;
  let pendingOrderSave: Promise<void> | undefined;
  try {
    if (!option.data) {
      if (opts?.requirePreparedQuote || account.provider === "Polymarket") {
        result = new BetResult(option.type, false, option.checkError || "预检未通过");
      }
      else {
        option = await checkBetting(store, account, option);
        if (!option.data)
          result = new BetResult(option.type, false, option.checkError || "预检失败");
      }
    }
    if (option.data) {
      try { observeOption(option, account, "submission_started", { source: "adapter_call" }); }
      catch { /* 观察失败不阻断已预检的场馆发送。 */ }
      observationSubmitted = true;
      observationCallAt = Date.now();
      result = await provider.betting(account, option);
      observationDuration = Date.now() - observationCallAt;
      if (account.provider === "Polymarket" && result.pending) {
        pendingOrderSave = persistPendingPmOrder(account, option, result);
        void pendingOrderSave.catch(error => { console.warn("[Polymarket] 待确认订单保存失败", error); });
        // 收到场馆回执即可继续；完整订单保存与官方确认并行，终态写入等待该保存。
      }
      // PM matched：官方 POST 成交即真相，立刻落库，勿干等 /data/trades
      if (result.success && !result.pending && account.provider === "Polymarket") {
        try {
          const saved = await persistPolymarketMatchedBuyOrder(account, option, result);
          observeOption(option, account, "bind_result", { orderId: result.orderId || undefined, outcome: saved ? "saved" : "unknown", source: "pm_optimistic_persist" });
          // 供手动/正EV：乐观落库失败时回退 waitForOrderId
          if (saved)
            result.tip = { pmOptimisticSaved: true };
        }
        catch {
          observeOption(option, account, "bind_result", { orderId: result.orderId || undefined, outcome: "failed", source: "pm_optimistic_persist" });
          /* 乐观落库失败不阻断下单成功；后续 Io.f / updateVenueOrders 仍可补 */
        }
      }
      // PM 已 POST 未成交（含无官方 orderId）：落库 Reject，供拒单率统计
      else if (!result.success && !result.pmSubmitUnknown && account.provider === "Polymarket") {
        try {
          if (Number(beginTime) > 0)
            result.beginTime = beginTime;
          await persistPolymarketExecutionReject(account, result, "api_failed", {
            betOption: option,
            linkId: opts?.linkId,
          });
        }
        catch {
          /* 拒单落库失败不阻断下单结果回传 */
        }
      }
    }
  }
  catch (e) {
    const raw = e instanceof Error ? e.message : String(e);
    observationThrew = true;
    observationError = e;
    if (observationCallAt !== undefined)
      observationDuration = Date.now() - observationCallAt;
    const message = raw.includes("Failed to fetch dynamically imported module")
      ? "页面资源已过期（服务端刚发版），请刷新页面后重试"
      : raw;
    result = new BetResult(
      account.provider,
      false,
      message,
      option.data,
    );
    // POST 前抛错 / 页面过期：不落拒单（无 pmPosted）
  }
  finally {
    result.link = result.pmSubmitUnknown && result.link > 0 ? result.link : Number(opts?.linkId || option.diagnosticLinkId) || 0;
    result.diagnosticAttempt = option.diagnosticAttempt;
    try {
      result.observation = option.observation;
      observeOption(option, account, "submission_result", {
        orderId: result.orderId || undefined,
        outcome: result.pmSubmitUnknown || observationThrew && observationSubmitted ? "unknown" : result.success ? "accepted" : observationSubmitted ? "adapter_failed" : "not_submitted",
        source: "adapter_result",
        observedStatus: submissionVenueStatus(result),
        durationMs: observationDuration,
        ...(!result.success ? observationFailureEvidence(result.message, result.response, observationError, result.provider) : {}),
      });
    }
    catch { /* 旁路写入或快照错误不能改变已取得的下注结果 */ }
    loading.close();
    const notifyType = result.pending ? "warning" : result.success ? "success" : "error";
    const statusSuffix = result.pending ? "确认中" : "";
    showBetResultNotification(notificationDisplay, {
      messageHtml: `<p>${result.message || ""}</p>`,
      statusSuffix,
      type: notifyType,
    }, toastSeconds);
    try { useMessageStore().delayMessage(account, Date.now() - beginTime); }
    catch { /* 延迟统计失败不改变已取得的场馆回执。 */ }
    try { result.saveLog(account, beginTime); }
    catch { /* 日志失败不丢弃真实回执或触发重复下单。 */ }
    if (result.success && !result.pending) {
      try { void playOrderSuccessSound({ betRowId: option.betId }).catch(() => {}); }
      catch { /* 成功音效失败不改变成交结果。 */ }
      try { void publishBettingEvent(option).catch(() => {}); }
      catch { /* 广播失败不改变成交结果。 */ }
    }
    if (
      result.pending
      && !option.loseOrder
      && isPendingConfirmVenueProvider(account.provider)
      && !option.deferPostAcceptSettlement
    ) {
      notifyPendingVenueConfirm(
        store,
        account,
        accountLine,
        detailHtml,
        result,
        option,
        toastSeconds,
        pendingOrderSave,
      );
    }
  }
  return result;
}

import type { BetOption } from "@changmen/client-core/models/betOption";
import type { BetResult } from "@changmen/client-core/models/betResult";
import type { PlatformAccount } from "@/models/platformAccount";
import type { VenueOrder } from "@changmen/venue-browser/adapter/contract";
import { pmSubmissionFromResult } from "@changmen/shared/pm_submission";
import { scaleUsdtToCnyDisplay } from "@changmen/shared/currency";
import { wait } from "@changmen/client-core/shared/wait";
import { getAuthSessionVersion, isAuthSessionCurrent } from "@/api/client";
import { saveOrders } from "@/api/order";
import { resolveOrderItemLabel } from "@/shared/orderItemDisplay";
import { refreshOrderListAfterBind } from "@/stores/betting/arbOrderBind";

/** [changmen 扩展] delayed/提交未知仍是同一笔订单；Pending 不代表已成交持仓。 */
export async function persistPendingPmOrder(
  account: PlatformAccount, option: BetOption, result: BetResult,
): Promise<void> {
  if (account.provider !== "Polymarket" || !result.pending) return;
  const submission = pmSubmissionFromResult(result, account.accountId);
  if (!submission) throw new Error("PM 提交记录缺失，无法保存待确认订单");
  const match = String(option.match?.title ?? "");
  const target = String(option.target ?? "");
  const named = option.target === "Away" ? option.bet?.awayName : option.bet?.homeName;
  const order: VenueOrder = {
    provider: "Polymarket", orderId: submission.orderId, status: "pending",
    createAt: submission.submittedAt, odds: Number(option.odds) || 0,
    betMoney: scaleUsdtToCnyDisplay(submission.stakeUsdc), money: 0, reward: 0,
    game: String(option.match?.game ?? ""), match,
    bet: String(option.bet?.getBetName?.() ?? ""),
    item: String(named ?? "").trim() || resolveOrderItemLabel(target, match) || target,
    pmSubmission: submission, pmSide: "buy", pmOrigin: "changmen",
    pmConditionId: option.betId, pmTokenId: option.itemId,
    venueMatchId: String(option.matchId), venueItemId: target,
    ...(Number(option.diagnosticLinkId) ? { link: Number(option.diagnosticLinkId) } : {}),
  };
  const version = getAuthSessionVersion();
  for (let attempt = 0; ; attempt++) {
    if (!isAuthSessionCurrent(version)) throw new Error("会话已切换，停止保存待确认订单");
    try { await saveOrders(account, [order]); break; }
    catch {
      // 只重试同一份订单写入；不能在缺少完整订单时另建一条无名称的拒单。
      await wait(Math.min(30_000, 500 * 2 ** Math.min(attempt, 6)));
    }
  }
  if (isAuthSessionCurrent(version)) refreshOrderListAfterBind();
}

import type { VenueOrder } from "@changmen/venue-browser/adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import type { OrderRow, PageResult } from "@/types/esport";
import { post, unwrap } from "@/api/client";
import type { PmSubmission, PmPendingOrderReceipt } from "@changmen/shared/pm_submission";

/** [changmen 扩展] 同步专用投影；未注册或没有匹配原单时沿用原保存数组。 */
let orderSyncProjection: ((account: PlatformAccount, orders: VenueOrder[]) => VenueOrder[] | Promise<VenueOrder[]>) | undefined;
export function registerOrderSyncProjection(project: NonNullable<typeof orderSyncProjection>): () => void {
  orderSyncProjection = project;
  return () => { if (orderSyncProjection === project) orderSyncProjection = undefined; };
}

/** [changmen 扩展] 旧待确认队列按原单恢复申请额，不能从当前赔率推算。 */
export async function getPmSubmission(playerId: number, orderId: string): Promise<PmSubmission | null> {
  const response = await post<PmSubmission>("Pm_GetSubmission", { playerId, orderId }, "", { errorTip: false });
  return response.success === 1 ? response.info ?? null : null;
}

/** [changmen 扩展] 从 RDS 读取待确认订单，刷新恢复不依赖名称缓存。 */
export async function getPendingPmOrders(playerId: number): Promise<PmPendingOrderReceipt[]> {
  const response = await post<PmPendingOrderReceipt[]>("Pm_GetPendingOrders", { playerId }, "", { errorTip: false });
  if (response.success !== 1) throw new Error(response.msg || "待确认订单读取失败");
  return response.info ?? [];
}

/** [A8 可证实] `Ut.getOrders`：success!==1 时不更新侧栏（返回 null） */
export async function getOrderList(body: Record<string, unknown> = {}) {
  const data = await post<PageResult<OrderRow>>("Client_GetOrderList", body);
  if (data.success !== 1)
    return null;
  return data.info ?? { list: [], total: 0, pageIndex: 1, pageSize: 20 };
}

export async function saveOrder(body: Record<string, unknown>) {
  return unwrap(await post<unknown>("Client_SaveOrder", body));
}

/**
 * 对齐 bundle `Vt.saveOrders`：按 provider 分组调用 `Client_SaveOrder`。
 * [changmen 扩展] PredictFun 禁止客户端回写：订单只经 Pf_* 服务端落库。
 */
export async function saveOrders(account: PlatformAccount, orders: VenueOrder[]): Promise<void> {
  orders = await (orderSyncProjection?.(account, orders) ?? orders);
  if (String(account.provider ?? "").trim() === "PredictFun")
    return;
  const byProvider = new Map<string, VenueOrder[]>();
  for (const order of orders) {
    const provider = String(order.provider ?? "").trim();
    if (provider === "PredictFun")
      continue;
    const list = byProvider.get(provider) ?? [];
    list.push(order);
    byProvider.set(provider, list);
  }
  for (const [type, list] of byProvider) {
    await saveOrder({
      type,
      playerId: account.accountId,
      orders: JSON.stringify(list),
    });
  }
}

/**
 * [A8 可证实] `Vt.saveOrderBind`：空数组不 POST。
 * [changmen 扩展] 返回是否成功（业务失败不抛，供绑单重试/UI 感知）。
 */
export async function saveOrderBind(body: Record<string, unknown>): Promise<boolean> {
  const raw = body.orders;
  if (typeof raw === "string") {
    try {
      const rows = JSON.parse(raw) as unknown[];
      if (!rows?.length)
        return true;
    }
    catch {
      // 非 JSON 时仍交给服务端
    }
  }
  const data = await post<boolean>("Client_SaveOrderBind", body, "", { errorTip: false });
  return data.success === 1;
}

/** [changmen 扩展] 侧栏手动改绑：单笔订单 link 新→老 */
export async function rebindOrderLink(body: {
  orderId: string;
  toLinkId: number;
}): Promise<{ orderId: string; fromLinkId: number; toLinkId: number }> {
  return unwrap(
    await post<{ orderId: string; fromLinkId: number; toLinkId: number }>(
      "Client_RebindOrderLink",
      body,
    ),
  );
}

